import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardMedia,
  CardContent,
  Typography,
  Button,
  Stack,
  useTheme
} from '@mui/material';
import callApi from '../../Services/callApi';
import { IProduct } from '../../Interface/IProduct';

type Product = {
  id: string;
  name: string;
  image: string;
  price: number;
  description?: string;
};

type Props = {

};


const ProductCatalog: React.FC<Props> = () => {
  const [products, setProducts] = useState<IProduct[]>([]);
  const theme = useTheme();

  useEffect(() => {
    onLoad();
  }, [

  ])

  const onLoad = async () => {
    const rs = await callApi.get('/Product/list');
    if (rs.data?.data) {
      setProducts(rs.data?.data);
    }
  }
  return (
    <Box p={2}>
      {/* Title with colored bar */}
      <Box
        display="flex"
        alignItems="center"
        mb={2}
        sx={{ width: '100%' }}
      >
        <Box
          sx={{
            width: 6,
            height: 24,
            backgroundColor: theme.palette.primary.main,
            borderRadius: 1,
            mr: 1.5,
          }}
        />
        <Typography variant="h6" fontWeight={600}>
          สินค้าแนะนำ
        </Typography>
      </Box>

      {/* Product List */}
      <Box
        display="flex"
        flexWrap="wrap"
        justifyContent="center"
        gap={2}
      >
        {products.map((product: IProduct) => (
          <Box
            key={product.id}
            sx={{
              width: 'calc(33.333% - 16px)',
              maxWidth: 200,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              borderRadius: 2,
              boxShadow: 1,
              overflow: 'hidden',
            }}
          >
            <Box
              component="img"
              src={product.imageUrl}
              alt={product.name}
              sx={{
                width: '100%',
                height: 140,
                objectFit: 'cover',
                display: 'block',
              }}
            />
            <Typography
              variant="body2"
              mt={1}
              sx={{
                width: '100%',
                textAlign: 'center',
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                fontWeight: 300,
              }}
            >
              {product.name}
            </Typography>
          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default ProductCatalog;
